<div class="modal hidden" id="productModal" role="dialog" aria-modal="true" aria-labelledby="detailTitle"><div class="dialog wide-dialog"><div class="dialog-head"><div><h2 id="detailTitle">Product details</h2><p>Choose an access period and review its price.</p></div><button class="close" data-close="productModal" aria-label="Close">×</button></div><div class="dialog-body" id="productDetailBody"></div></div></div>
<div class="modal hidden" id="purchaseChoiceModal" role="dialog" aria-modal="true" aria-labelledby="purchaseChoiceTitle"><div class="dialog"><div class="dialog-head"><div><h2 id="purchaseChoiceTitle">Choose payment method</h2><p id="purchaseProduct"></p></div><button class="close" data-close="purchaseChoiceModal" aria-label="Close">×</button></div><div class="dialog-body"><div class="choice-detail"><div id="purchaseDisplayPrice"></div><div id="purchaseInrPrice"></div><div id="walletChoiceBalance" class="muted"></div></div><div class="hint">USD is a display option where configured. Wallet and gateway settlement remain in INR.</div><div class="choice-actions"><button class="button secondary" id="payWalletButton">Pay from wallet</button><button class="button" id="payOnlineButton">Pay online</button></div><div class="error" id="purchaseChoiceError"></div></div></div></div>
<div class="modal hidden" id="authModal" role="dialog" aria-modal="true" aria-labelledby="authTitle"><div class="dialog"><div class="dialog-head"><div><h2 id="authTitle">Your shop account</h2><p>Sign in to checkout and keep your order keys together.</p></div><button class="close" data-close="authModal" aria-label="Close">×</button></div><div class="dialog-body"><div class="tabs"><button class="tab active" id="loginTab">Sign in</button><button class="tab" id="registerTab">Create account</button></div><form id="authForm"><div class="field hidden" id="nameField"><label for="displayName">Display name</label><input id="displayName" maxlength="100" autocomplete="name"></div><div class="field"><label for="email">Email</label><input id="email" type="email" maxlength="254" required autocomplete="email"></div><div class="field"><label for="password">Password</label><input id="password" type="password" minlength="10" maxlength="256" required autocomplete="current-password"></div><button class="button wide" id="authSubmit" type="submit">Sign in</button><div class="error" id="authError"></div></form><p class="hint">Email accounts require a password of at least 10 characters. Your account keeps your order history and delivery keys together.</p></div></div></div>
<div class="modal payment-modal hidden" id="paymentModal" role="dialog" aria-modal="true" aria-labelledby="paymentTitle"><div class="dialog"><div class="dialog-head"><div><h2 id="paymentTitle">Complete payment</h2><p id="paymentSubtitle">After paying, leave this window open while we verify your order.</p></div><button class="close" data-close="paymentModal" aria-label="Close">×</button></div><div class="dialog-body"><div class="payment-details" id="paymentDetails"></div><img class="payment-qr" id="paymentQr" alt="Payment QR code"><a class="button wide" id="paymentLink" target="_blank" rel="noreferrer">Open secure payment page</a><section id="binanceProofArea" class="hidden"><div class="hint" id="binanceInstructions"></div><form id="binanceProofForm"><div class="field"><label for="binanceTxid">Binance transaction ID</label><input id="binanceTxid" maxlength="180" required></div><div class="field"><label for="binanceProof">Payment screenshot (PNG, JPEG, WebP · max 5 MB)</label><input id="binanceProof" type="file" accept="image/png,image/jpeg,image/webp" required></div><button class="button wide" id="submitBinanceProof" type="submit">Submit payment proof</button></form></section><div class="hint" id="paymentStatus">Waiting for payment…</div><div class="payment-actions"><button class="button secondary" id="checkPayment">Check payment</button><button class="button ghost" data-close="paymentModal">Close</button></div></div></div></div>
<div class="toast hidden" id="toast" role="status"></div><script src="/storefront.js" defer></script></body></html>
